import { createDocument } from '../core/document.js';
import { renderLines } from '../io/render.js';
import { parseCommandLine } from './parse.js';

// Repeats undo or redo up to `count` times; says so when not even one step was possible.
function step(document, name, count, out) {
  const move = name === 'undo' ? () => document.undo() : () => document.redo();
  let moved = 0;
  while (moved < count && move()) moved += 1;
  if (count > 0 && moved === 0) out('nothing to ' + name);
}

// Runs a script, one command per line, and returns the document.
export function run(script, { out, document = createDocument() }) {
  for (const raw of script.split('\n')) {
    if (!raw.trim()) continue;
    const { name, number, text } = parseCommandLine(raw);
    try {
      switch (name) {
        case 'insert':
          document.insert(number, text);
          break;
        case 'delete':
          document.delete(number);
          break;
        case 'replace':
          document.replace(number, text);
          break;
        case 'undo':
        case 'redo':
          step(document, name, number ?? 1, out);
          break;
        case 'print':
          for (const line of renderLines(document.lines())) out(line);
          break;
        default:
          out('error: unknown command: ' + name);
      }
    } catch (error) {
      out('error: ' + error.message);
    }
  }
  return document;
}

import { deleteLine, insertLine, replaceLine } from './buffer.js';
import { createHistory } from './history.js';

// A document holds lines of text. Line numbers start at 1; an edit with a
// bad line number throws a RangeError and changes nothing, and is not
// recorded in the history. The last `historyLimit` edits can be undone.
export function createDocument(initial = [], { historyLimit = 100 } = {}) {
  let lines = [...initial];
  const history = createHistory(historyLimit);
  const edit = (change) => {
    const next = change(lines);
    history.record(lines);
    lines = next;
  };
  const move = (step) => {
    const target = step(lines);
    if (target === undefined) return false;
    lines = target;
    return true;
  };
  return {
    lines: () => [...lines],
    text: () => lines.join('\n'),
    insert: (n, text) => edit((current) => insertLine(current, n, text)),
    delete: (n) => edit((current) => deleteLine(current, n)),
    replace: (n, text) => edit((current) => replaceLine(current, n, text)),
    undo: () => move((current) => history.undo(current)),
    redo: () => move((current) => history.redo(current)),
    canUndo: () => history.canUndo(),
    canRedo: () => history.canRedo(),
  };
}

// Bounded undo and redo stacks of snapshots. Snapshots are never changed in
// place, so they can be stored as they are.
export function createHistory(limit) {
  let undoStack = [];
  let redoStack = [];
  return {
    // Remembers the state before an edit and forgets anything that could be redone.
    record(snapshot) {
      redoStack = [];
      if (limit <= 0) return;
      undoStack.push(snapshot);
      if (undoStack.length > limit) undoStack.shift();
    },
    // Takes the current state, returns the one to go back to (undefined if none).
    undo(current) {
      if (undoStack.length === 0) return undefined;
      redoStack.push(current);
      return undoStack.pop();
    },
    redo(current) {
      if (redoStack.length === 0) return undefined;
      undoStack.push(current);
      return redoStack.pop();
    },
    canUndo: () => undoStack.length > 0,
    canRedo: () => redoStack.length > 0,
  };
}

export { insertLine, deleteLine, replaceLine } from './core/buffer.js';
export { createDocument } from './core/document.js';
export { createHistory } from './core/history.js';
export { parseCommandLine } from './cli/parse.js';
export { renderLines } from './io/render.js';
export { run } from './cli/repl.js';
